/**
 * TASK: Complete getSelectedTheme and refresh for a radio button theme picker.
 *
 * The three radio buttons already share one ButtonGroup and each one carries an
 * action command: "light", "dark", "high-contrast".
 *
 * getSelectedTheme returns the action command of the chosen button, or "none"
 * when nothing has been chosen yet.
 * refresh sets the label to "Theme: dark" (the word Theme, a colon, a space,
 * then whatever getSelectedTheme returns).
 *
 * refresh already runs at construction time and after every button click.
 */
import javax.swing.ButtonGroup;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JRadioButton;

public class RadioThemeSelector extends JPanel {

    private final JRadioButton light = new JRadioButton("Light");
    private final JRadioButton dark = new JRadioButton("Dark");
    private final JRadioButton highContrast = new JRadioButton("High contrast");
    private final ButtonGroup group = new ButtonGroup();
    private final JLabel themeLabel = new JLabel("(unset)");

    public RadioThemeSelector() {
        light.setName("light");
        dark.setName("dark");
        highContrast.setName("highContrast");
        themeLabel.setName("themeLabel");
        light.setActionCommand("light");
        dark.setActionCommand("dark");
        highContrast.setActionCommand("high-contrast");
        for (JRadioButton button : new JRadioButton[] { light, dark, highContrast }) {
            group.add(button);
            button.addActionListener(e -> refresh());
            add(button);
        }
        add(themeLabel);
        refresh();
    }

    public String getSelectedTheme() {
        // TODO: return the selected button's action command, or "none"
        return "";
    }

    public void refresh() {
        // TODO: show the current theme in themeLabel
    }
}

