public class RadioThemeSelectorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String labelText(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        return "(missing)";
    }

    static javax.swing.JRadioButton radio(java.awt.Container root, String name) {
        java.awt.Component c = find(root, name);
        return (c instanceof javax.swing.JRadioButton) ? (javax.swing.JRadioButton) c : null;
    }

    public static void main(String[] args) {
        try {
            RadioThemeSelector panel = new RadioThemeSelector();
            javax.swing.JRadioButton light = radio(panel, "light");
            javax.swing.JRadioButton dark = radio(panel, "dark");
            javax.swing.JRadioButton hc = radio(panel, "highContrast");
            java.awt.Component label = find(panel, "themeLabel");
            check("all three radio buttons found", true, light != null && dark != null && hc != null);
            check("no theme chosen yet", "none", panel.getSelectedTheme());
            check("startup label", "Theme: none", labelText(label));
            if (light != null && dark != null && hc != null) {
                dark.doClick();
                check("after choosing dark", "dark", panel.getSelectedTheme());
                check("label after choosing dark", "Theme: dark", labelText(label));
                hc.doClick();
                check("action command wins over button text", "high-contrast", panel.getSelectedTheme());
                light.doClick();
                check("group keeps only one selected", false, hc.isSelected());
                check("label after choosing light", "Theme: light", labelText(label));
            } else {
                failures++;
                System.out.println("FAIL  one or more radio buttons not found by name");
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

