import javax.swing.ButtonGroup;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JRadioButton;

public class RadioThemeSelector extends JPanel {

    private final JRadioButton light = new JRadioButton("Light");
    private final JRadioButton dark = new JRadioButton("Dark");
    private final JRadioButton highContrast = new JRadioButton("High contrast");
    private final ButtonGroup group = new ButtonGroup();
    private final JLabel themeLabel = new JLabel("(unset)");

    public RadioThemeSelector() {
        light.setName("light");
        dark.setName("dark");
        highContrast.setName("highContrast");
        themeLabel.setName("themeLabel");
        light.setActionCommand("light");
        dark.setActionCommand("dark");
        highContrast.setActionCommand("high-contrast");
        for (JRadioButton button : new JRadioButton[] { light, dark, highContrast }) {
            group.add(button);
            button.addActionListener(e -> refresh());
            add(button);
        }
        add(themeLabel);
        refresh();
    }

    public String getSelectedTheme() {
        javax.swing.ButtonModel selected = group.getSelection();
        if (selected == null) {
            return "none";
        }
        return selected.getActionCommand();
    }

    public void refresh() {
        themeLabel.setText("Theme: " + getSelectedTheme());
    }
}
